from pathlib import Path
path = Path('src/data_interface/increment_manager.rs')
text = path.read_text(encoding='utf-8')
start_token = '                                let file_name = match path.file_stem().and_then(|s| s.to_str()) {\r\n                                    Some(name) => name,'
start = text.index(start_token)
end_token = '                                        notify_file_names.push(file_name.to_owned());\r\n                                    }\r\n                                }\r\n'
end = text.index(end_token, start) + len(end_token)
new_block = '''                                let file_name = match path.file_stem().and_then(|s| s.to_str()) {\r\n                                    Some(name) => name,\r\n                                    None => {\r\n                                        println!(\"无法从新文件路径中解析文件名: {:?}\", path);\r\n                                        continue;\r\n                                    }\r\n                                };\r\n\r\n                                let dbno = new_header.pdms_header.db_num as u32;\r\n                                let current_sesno = new_header.latest_ses_data.sesno;\r\n\r\n                                if let Some(location_dbs) = &get_db_option().location_dbs {\r\n                                    if !location_dbs.contains(&dbno) {\r\n                                        continue;\r\n                                    }\r\n                                }\r\n\r\n                                if current_sesno > 0 {\r\n                                    params.insert(\r\n                                        path.clone(),\r\n                                        (new_header.clone(), 1..=current_sesno),\r\n                                    );\r\n                                }\r\n\r\n                                #[cfg(any(feature = \"mqtt\", feature = \"web_server\"))]\r\n                                let (output, archive_hash) = {\r\n                                    let output: PathBuf = format!(\"assets/archives/{}.cba\", file_name).into();\r\n                                    let compress_opt = CompressOptions::new(\r\n                                        path.clone(),\r\n                                        output.clone(),\r\n                                        \"assets/temp\",\r\n                                    );\r\n                                    let hash = match execute_compress(compress_opt).await {\r\n                                        Ok(h) => h.to_string(),\r\n                                        Err(e) => {\r\n                                            println!(\"新文件压缩生成 CBA 失败: {:?}, 路径: {:?}\", e, path);\r\n                                            continue;\r\n                                        }\r\n                                    };\r\n                                    (output, hash)\r\n                                };\r\n\r\n                                #[cfg(feature = \"web_server\")]\r\n                                {\r\n                                    let archive_size = std::fs::metadata(&output)\r\n                                        .map(|m: std::fs::Metadata| m.len())\r\n                                        .unwrap_or(0);\r\n                                    generated_artifacts.push(GeneratedSyncArtifact {\r\n                                        path: output.clone(),\r\n                                        file_name: format!(\"{}.cba\", file_name),\r\n                                        file_size: archive_size,\r\n                                        file_hash: Some(archive_hash.clone()),\r\n                                        record_count: if current_sesno > 0 {\r\n                                            Some(current_sesno as u64)\r\n                                        } else {\r\n                                            None\r\n                                        },\r\n                                        db_num: Some(dbno),\r\n                                        db_path: path.to_str().map(|s| s.to_string()),\r\n                                        old_sesno: None,\r\n                                        new_sesno: Some(current_sesno),\r\n                                        session_range: Some(format!(\"1-{}\", current_sesno)),\r\n                                        generated_at: Some(SystemTime::now()),\r\n                                        is_full_sync: true,\r\n                                    });\r\n                                }\r\n\r\n                                #[cfg(feature = \"mqtt\")]\r\n                                {\r\n                                    let sql = format!(\r\n                                        \"select value <string>\\\\\nid from (select * from e3d_sync where location != '{}' and '{}' in file_names and '{}' in file_hashes order by timestamp desc) \",\r\n                                        get_db_option().location.as_str(),\r\n                                        file_name,\r\n                                        &archive_hash\r\n                                    );\r\n                                    let mut response = SUL_DB.query(&sql).await.unwrap();\r\n                                    let id = response.take::<Vec<String>>(0).unwrap();\r\n                                    if id.is_empty() {\r\n                                    println!(\"发现新增 db 文件，推送：{}\", &file_name);\r\n                                        notify_file_hashes.push(archive_hash.clone());\r\n                                        notify_file_names.push(file_name.to_owned());\r\n                                    }\r\n                                }\r\n'''
text = text[:start] + new_block + text[end:]
path.write_text(text, encoding='utf-8')
